import{o as s,c as n,a6 as r,j as t,k as o,g as d,a}from"./chunks/framework.DMOj2-2K.js";const l={class:"brand-logos"},i={class:"on-light"},c=["src"],h={class:"on-dark"},u=["src"],g={class:"on-light"},b=["src"],f={class:"on-dark"},k=["src"],m={class:"on-light"},p=["src"],v={class:"on-light"},y=["src"],E=JSON.parse('{"title":"Brand & logo","description":"","frontmatter":{},"headers":[],"relativePath":"brand.md","filePath":"brand.md"}'),_={name:"brand.md"},T=Object.assign(_,{setup(w){return(B,e)=>(s(),n("div",null,[e[6]||(e[6]=r('<h1 id="brand-logo" tabindex="-1">Brand &amp; logo <a class="header-anchor" href="#brand-logo" aria-label="Permalink to &quot;Brand &amp; logo&quot;">​</a></h1><p>Cluub <em>clubs together</em> the frontend, the backend and AI. The logo hides a little joke in the name: the <strong>uu</strong> of cluub becomes the cat&#39;s happy, closed <strong>eyes</strong>, drawn as two big white letters, so the logo reads <em>cl</em>, then a cat, then <em>b</em>, and the cat <em>is</em> the double u. The cat is friendly, curious and quick, which is how Cluub should feel to use.</p><h2 id="logo-files" tabindex="-1">Logo files <a class="header-anchor" href="#logo-files" aria-label="Permalink to &quot;Logo files&quot;">​</a></h2><p>All files are plain SVG in the repository&#39;s <code>docs/public/</code> folder and are served from this site.</p>',4)),t("div",l,[t("figure",i,[t("img",{src:o(d)("/logo-full.svg"),alt:"Cluub logo: the letters c and l, a cat face whose eyes are the uu, and the letter b, for light backgrounds"},null,8,c),e[0]||(e[0]=t("figcaption",null,[t("code",null,"/logo-full.svg"),a(" · light backgrounds")],-1))]),t("figure",h,[t("img",{src:o(d)("/logo-full-dark.svg"),alt:"Cluub logo with light letters, for dark backgrounds"},null,8,u),e[1]||(e[1]=t("figcaption",null,[t("code",null,"/logo-full-dark.svg"),a(" · dark backgrounds")],-1))]),t("figure",g,[t("img",{src:o(d)("/logo.svg"),alt:"Cluub cat icon"},null,8,b),e[2]||(e[2]=t("figcaption",null,[t("code",null,"/logo.svg"),a(" · icon")],-1))]),t("figure",f,[t("img",{src:o(d)("/logo-dark.svg"),alt:"Cluub cat icon on a dark background"},null,8,k),e[3]||(e[3]=t("figcaption",null,[t("code",null,"/logo-dark.svg"),a(" · icon on dark")],-1))]),t("figure",m,[t("img",{src:o(d)("/wordmark.svg"),alt:"Cluub wordmark without the cat"},null,8,p),e[4]||(e[4]=t("figcaption",null,[t("code",null,"/wordmark.svg"),a(" · plain wordmark")],-1))]),t("figure",v,[t("img",{src:o(d)("/favicon.svg"),alt:"Cluub favicon"},null,8,y),e[5]||(e[5]=t("figcaption",null,[t("code",null,"/favicon.svg"),a(" · favicon")],-1))])]),e[7]||(e[7]=r('<p>The letters are drawn with simple strokes (no font), so the logo looks identical everywhere and needs no font licence. The cat icon works on light and dark backgrounds alike; use <code>/wordmark.svg</code> where a playful mark doesn&#39;t fit (for example in plain-text contexts).</p><h3 id="anatomy-of-the-cat" tabindex="-1">Anatomy of the cat <a class="header-anchor" href="#anatomy-of-the-cat" aria-label="Permalink to &quot;Anatomy of the cat&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Part</th><th>Colour</th><th>Why</th></tr></thead><tbody><tr><td>Face and ears</td><td>Blue <code>#0072B2</code>, inner ears sky <code>#56B4E9</code></td><td>The brand colour; 5.2 : 1 against white</td></tr><tr><td>Eyes <strong>uu</strong></td><td>White</td><td>The <strong>uu</strong> of cluub, as happy closed eyes; 5.2 : 1 on the blue face</td></tr><tr><td>Nose</td><td>Orange <code>#E69F00</code></td><td>Warm accent from the palette</td></tr><tr><td>Mouth</td><td>White</td><td>A small smile</td></tr><tr><td>Whiskers</td><td>Orange <code>#E69F00</code></td><td>Accent; 7.6 : 1 on dark backgrounds</td></tr></tbody></table><h2 id="colours" tabindex="-1">Colours <a class="header-anchor" href="#colours" aria-label="Permalink to &quot;Colours&quot;">​</a></h2><p>Cluub uses the <strong>Okabe–Ito palette</strong>, a set of colours designed to stay distinguishable for people with colour-vision deficiency.</p><div class="brand-swatches"><div style="background:#0072B2;color:#fff;"><b>Blue #0072B2</b><br>Brand colour, cat face</div><div style="background:#E69F00;color:#1E293B;"><b>Orange #E69F00</b><br>Nose, whiskers</div><div style="background:#009E73;color:#fff;"><b>Green #009E73</b><br>Accents</div><div style="background:#1E293B;color:#fff;"><b>Ink #1E293B</b><br>Letters, text</div><div style="background:#56B4E9;color:#0B1220;"><b>Sky #56B4E9</b><br>Brand colour on dark</div><div style="background:#CC79A7;color:#1E293B;"><b>Reddish purple #CC79A7</b><br>AI in diagrams</div><div style="background:#A84B00;color:#fff;"><b>Deep vermillion #A84B00</b><br>Errors (shade of #D55E00)</div></div><p>The same palette is used everywhere: the logo, this site, the diagrams, the playground and the default theme of every Cluub app. Text on a coloured background is white on blue and deep vermillion, and ink <code>#1E293B</code> on sky, green, orange and reddish purple, all at 4.3 : 1 or more.</p><table tabindex="0"><thead><tr><th>Token</th><th>Hex</th><th>Used for</th><th>Contrast (measured)</th></tr></thead><tbody><tr><td>Blue</td><td><code>#0072B2</code></td><td>Cat face, links and buttons on light backgrounds</td><td>5.2 : 1 on white; 3.3 : 1 on <code>#1B1B1F</code></td></tr><tr><td>Orange</td><td><code>#E69F00</code></td><td>Nose, whiskers</td><td>7.6 : 1 on <code>#1B1B1F</code>; decorative on white</td></tr><tr><td>Green</td><td><code>#009E73</code></td><td>Accents in the docs</td><td>Decorative</td></tr><tr><td>Ink</td><td><code>#1E293B</code></td><td>Letters, body text</td><td>14.6 : 1 on white</td></tr><tr><td>Sky</td><td><code>#56B4E9</code></td><td>Links and buttons on dark backgrounds</td><td>7.4 : 1 on <code>#1B1B1F</code></td></tr><tr><td>Reddish purple</td><td><code>#CC79A7</code></td><td>AI in diagrams</td><td>Ink text on it: 4.8 : 1</td></tr><tr><td>Deep vermillion</td><td><code>#A84B00</code></td><td>Error messages and toasts (a darker shade of Okabe–Ito vermillion <code>#D55E00</code>)</td><td>White text on it: 5.7 : 1</td></tr><tr><td>Light ink</td><td><code>#F1F5F9</code></td><td>Letters on dark backgrounds</td><td>15.7 : 1 on <code>#1B1B1F</code></td></tr></tbody></table><p>Every part of the logo that carries meaning (face, the white <strong>uu</strong> eyes, letters) has at least 3 : 1 contrast against what&#39;s behind it, the WCAG level for graphics.</p><h3 id="colour-blind-check" tabindex="-1">Colour-blind check <a class="header-anchor" href="#colour-blind-check" aria-label="Permalink to &quot;Colour-blind check&quot;">​</a></h3><p>The cat doesn&#39;t depend on colour at all: the white <strong>uu</strong> eyes stand out from the blue face by brightness, not hue, so they read the same in greyscale, so it reads the same in greyscale and for every type of colour vision. The palette itself was checked with the Machado (2009) colour-vision simulation (CIEDE2000 ΔE between colours; above about 10 is clearly different):</p><table tabindex="0"><thead><tr><th>Vision</th><th>Blue / orange</th><th>Blue / green</th><th>Orange / green</th></tr></thead><tbody><tr><td>Typical</td><td>55.4</td><td>38.4</td><td>42.9</td></tr><tr><td>Protanopia (no red cones)</td><td>55.7</td><td>38.4</td><td>17.9</td></tr><tr><td>Deuteranopia (no green cones)</td><td>62.7</td><td>34.6</td><td>26.5</td></tr><tr><td>Tritanopia (no blue cones, rare)</td><td>51.4</td><td>12.4</td><td>55.5</td></tr></tbody></table><p>The same blue is the default <code>--primary</code> colour of every Cluub app, and the <a href="/cookbook/theming">default theme</a> uses <code>#56B4E9</code> in dark mode.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ul><li><strong>Do</strong> leave space around the logo at least as wide as one cat ear.</li><li><strong>Do</strong> use <code>/logo-full-dark.svg</code> on dark backgrounds (the cat icon works on both).</li><li><strong>Don&#39;t</strong> recolour, rotate, stretch or add effects to the logo.</li><li><strong>Don&#39;t</strong> change the eyes: the white <strong>uu</strong> is the heart of the logo.</li><li>The name is written <strong>Cluub</strong> in text and <strong>cluub</strong> for the command, the package and the wordmark.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/introduction#why-the-name-cluub">Why the name Cluub</a></li><li><a href="/cookbook/theming">Custom theme and styling</a></li></ul>',17))]))}});export{E as __pageData,T as default};
